CREATE TEMP TABLE purchase_credit_checks(name text,passed boolean);
CREATE FUNCTION pg_temp.assert(v boolean,n text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',n;END IF;INSERT INTO purchase_credit_checks VALUES(n,true);END$$;
CREATE FUNCTION pg_temp.stock_hash(c uuid) RETURNS text LANGUAGE sql AS $$SELECT md5(coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY item_id,warehouse_id)::text FROM public.bf_stock s WHERE cafe_id=c),'[]')||coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY id)::text FROM public.bf_movements m WHERE cafe_id=c),'[]'))$$;
CREATE FUNCTION pg_temp.source_hash(c uuid,d uuid) RETURNS text LANGUAGE sql AS $$SELECT md5((SELECT to_jsonb(x)::text FROM public.bf_documents x WHERE cafe_id=c AND id=d)||coalesce((SELECT jsonb_agg(to_jsonb(l) ORDER BY id)::text FROM public.bf_document_lines l WHERE cafe_id=c AND document_id=d),'[]')||coalesce((SELECT jsonb_agg(to_jsonb(j) ORDER BY id)::text FROM public.bf_journal j WHERE cafe_id=c AND document_id=d),'[]'))$$;
DO $$DECLARE c uuid:='d3000000-0000-4000-8000-000000000001';foreign_c uuid:='d3000000-0000-4000-8000-000000000002';owner_id uuid;other_id uuid;plan text;branch_a uuid:=gen_random_uuid();branch_b uuid:=gen_random_uuid();supplier uuid:=gen_random_uuid();item uuid:=gen_random_uuid();warehouse uuid;bank uuid;expense uuid;unit uuid;unitname text;record_id uuid:=gen_random_uuid();line_id uuid:=gen_random_uuid();invoice uuid;v_note uuid:=gen_random_uuid();delete_id uuid:=gen_random_uuid();cancel_id uuid:=gen_random_uuid();v_doc uuid;reversal uuid;second_document uuid;request_id uuid;post_request uuid;delete_request uuid;payment_request uuid;p jsonb;payload jsonb;result jsonb;prior jsonb;settings jsonb;stock_before text;source_before text;denied boolean;rev integer;claims jsonb;balance_before numeric;BEGIN
