 PERFORM brand_finance_private.seed(c);SELECT id INTO warehouse FROM public.bf_warehouses WHERE cafe_id=c AND active LIMIT 1;SELECT id INTO bank FROM public.bf_accounts WHERE cafe_id=c AND code='1010';SELECT id INTO expense FROM public.bf_accounts WHERE cafe_id=c AND code='5100';SELECT id,name INTO unit,unitname FROM public.bf_item_units WHERE cafe_id=c LIMIT 1;unitname:=coalesce(unitname,'unit');
 INSERT INTO public.branches(id,cafe_id,name,active) VALUES(branch_a,c,'PURCHASE-CREDIT-PROBE A',true),(branch_b,c,'PURCHASE-CREDIT-PROBE B',true);
