 INSERT INTO public.bf_items(id,cafe_id,name,sku,unit,unit_id,active) VALUES(item,c,'PURCHASE-CREDIT-PROBE item','PCN-PROBE',unitname,unit,true);
 payload:=jsonb_build_object('id',supplier,'revision',0,'name','PURCHASE-CREDIT-PROBE supplier','phone','','email','','taxNumber','','active',true,'firstName','','lastName','','mobile','','commercialRegistration','','number','','currency','SAR','address',jsonb_build_object('building','','street','','additional','','district','','city','','postal','','short','','country','SA'),'contacts','[]'::jsonb,'addresses','[]'::jsonb,'note','','openingBalance',0,'openingDate',current_date);
 PERFORM public.erp_purchases_write(c,'supplier',payload,gen_random_uuid());
 payload:=jsonb_build_object('id',record_id,'revision',0,'kind','invoice','title','PURCHASE-CREDIT-PROBE invoice','number','','date',current_date,'dueDate',NULL,'supplierId',supplier,'supplierIds',jsonb_build_array(supplier),'warehouseId',warehouse,'sourceId',NULL,'currency','SAR','exchangeRate',1,'taxInclusive',false,'discount',0,'shipping',0,'adjustment',0,'adjustmentAccountId',NULL,'paid',0,'accountId',NULL,'received',true,'note','PURCHASE-CREDIT-PROBE invoice','terms','','customStatus','','lines',jsonb_build_array(jsonb_build_object('id',line_id,'itemId',item,'description','PURCHASE-CREDIT-PROBE item','unit',unitname,'quantity',10,'price',10,'discount',0,'taxRate',15,'costCenterId',NULL)));
 PERFORM public.erp_purchases_write(c,'save',payload,gen_random_uuid());result:=public.erp_purchases_write(c,'post',jsonb_build_object('id',record_id,'revision',1,'expectedTotal',115),gen_random_uuid());invoice:=(result->>'financeId')::uuid;
 PERFORM pg_temp.assert((brand_finance_private.document_state(c,invoice)->>'outstanding')::numeric=115,'actual purchase posted payable');
 PERFORM pg_temp.assert(EXISTS(SELECT 1 FROM public.bf_stock WHERE cafe_id=c AND item_id=item AND quantity=10 AND value=100),'actual purchase received stock');
 PERFORM pg_temp.assert((SELECT branch_id=branch_a FROM public.erp_branch_documents WHERE cafe_id=c AND document_id=invoice),'actual source branch retained');
 stock_before:=pg_temp.stock_hash(c);source_before:=pg_temp.source_hash(c,invoice);
 p:=jsonb_build_object('id',v_note,'revision',0,'invoiceId',invoice,'date',current_date,'description','PURCHASE-CREDIT-PROBE additional charge','amount',50,'discount',10,'taxRate',15,'expenseAccountId',expense);
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'save',p,gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLSTATE IN('P0001','22023','22003','23514');END;PERFORM pg_temp.assert(denied,'disabled feature denies new credit note');
 settings:=erp_purchase_private.settings(c);INSERT INTO public.erp_purchase_settings(cafe_id,payload) VALUES(c,settings||'{"allowCreditNotes":true}') ON CONFLICT(cafe_id) DO UPDATE SET payload=excluded.payload;
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'save',p||jsonb_build_object('invoiceId',gen_random_uuid()),gen_random_uuid());EXCEPTION WHEN SQLSTATE 'P0001' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'missing original source cannot create payable');
 denied:=false;BEGIN UPDATE public.erp_purchase_settings t SET payload=t.payload||'{"allowCreditNotes":"true"}' WHERE cafe_id=c;EXCEPTION WHEN SQLSTATE 'P0001' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'nonboolean setting rejected');
 request_id:=gen_random_uuid();result:=public.erp_purchase_credit_write(c,'save',p,request_id);prior:=result;
 PERFORM pg_temp.assert(public.erp_purchase_credit_write(c,'save',p,request_id)=result,'save retry is idempotent');
 PERFORM pg_temp.assert((SELECT (n.payload->>'total')::numeric=46 FROM public.erp_purchase_credit_notes n WHERE id=v_note),'discount tax total canonical');
 PERFORM pg_temp.assert(pg_temp.stock_hash(c)=stock_before AND pg_temp.source_hash(c,invoice)=source_before,'draft does not change original source or stock');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'save',p-'revision',gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLSTATE IN('P0001','22023','22003','23514');END;PERFORM pg_temp.assert(denied,'missing revision rejected');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'save',p,gen_random_uuid());EXCEPTION WHEN SQLSTATE '40001' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'stale revision rejected');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'save',p||jsonb_build_object('id',gen_random_uuid(),'date','infinity'),gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLSTATE IN('P0001','22023','22003','23514');END;PERFORM pg_temp.assert(denied,'infinite date rejected');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'save',p||jsonb_build_object('description','changed'),request_id);EXCEPTION WHEN OTHERS THEN denied:=SQLSTATE IN('P0001','22023','22003','23514');END;PERFORM pg_temp.assert(denied,'request identity cannot bind changed payload');
 UPDATE public.bf_settings SET closed_through=current_date WHERE cafe_id=c;denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'post',jsonb_build_object('id',v_note,'revision',1,'expectedTotal',46),gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLSTATE IN('P0001','22023','22003','23514');END;PERFORM pg_temp.assert(denied,'closed period blocks posting');UPDATE public.bf_settings SET closed_through=NULL WHERE cafe_id=c;
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'post',jsonb_build_object('id',v_note,'revision',1),gen_random_uuid());EXCEPTION WHEN SQLSTATE '40001' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'missing expected total rejected');
 post_request:=gen_random_uuid();payload:=jsonb_build_object('id',v_note,'revision',1,'expectedTotal',46);result:=public.erp_purchase_credit_write(c,'post',payload,post_request);v_doc:=(result->>'documentId')::uuid;
 PERFORM pg_temp.assert(public.erp_purchase_credit_write(c,'post',payload,post_request)=result,'posting retry creates no second payable');
 PERFORM pg_temp.assert((brand_finance_private.document_state(c,v_doc)->>'outstanding')::numeric=46,'new document is actual extra payable');
 PERFORM pg_temp.assert((SELECT sum(j.credit-j.debit)=161 FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.party_id=supplier AND a.code='2000'),'supplier debt increases by46');
 PERFORM pg_temp.assert((SELECT sum(j.debit-j.credit)=40 FROM public.bf_journal j WHERE j.cafe_id=c AND j.document_id=v_doc AND j.account_id=expense),'net charge uses chosen expense');
 PERFORM pg_temp.assert(pg_temp.stock_hash(c)=stock_before AND pg_temp.source_hash(c,invoice)=source_before,'posting preserves stock and original financial source');
 PERFORM pg_temp.assert(NOT EXISTS(SELECT 1 FROM public.bf_document_lines WHERE cafe_id=c AND document_id=v_doc),'additional charge has no stock item lines');
 PERFORM pg_temp.assert(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.erp_purchases_read(c)->'invoices')x WHERE x->>'id'=v_doc::text),'main invoice list excludes extra payable artifact');
 PERFORM pg_temp.assert(EXISTS(SELECT 1 FROM jsonb_array_elements(public.erp_purchase_credit_read(c))x WHERE x->>'id'=v_note::text AND(x->>'outstanding')::numeric=46),'credit reader returns actual outstanding');
 INSERT INTO public.erp_branch_settings(cafe_id,payload) VALUES(c,'{"shareSuppliers":false}') ON CONFLICT(cafe_id) DO UPDATE SET payload=erp_branch_settings.payload||excluded.payload;
