 PERFORM pg_temp.assert(NOT erp_branch_private.allowed_resource(c,branch_a,'supplier',supplier),'fixture supplier actually unavailable in current branch');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'post',payload,post_request);EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'cached result rechecks source supplier availability in same branch');
 DELETE FROM public.erp_branch_resources br WHERE cafe_id=c AND kind='supplier' AND br.record_id=supplier;UPDATE public.erp_branch_settings t SET payload=t.payload||'{"shareSuppliers":true}' WHERE cafe_id=c;
