 DELETE FROM public.erp_branch_resources br WHERE cafe_id=c AND kind='account' AND br.record_id=expense;INSERT INTO public.erp_branch_resources(cafe_id,kind,record_id,branch_id) VALUES(c,'account',expense,branch_b);
