 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'draft',jsonb_build_object('id',v_note,'revision',2),gen_random_uuid());EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'existing mutation rechecks expense account permission');
 DELETE FROM public.erp_branch_resources br WHERE cafe_id=c AND kind='account' AND br.record_id=expense;UPDATE public.erp_branch_settings t SET payload=t.payload||'{"specifyAccounts":false}' WHERE cafe_id=c;
 UPDATE public.erp_branch_scopes SET branch_id=branch_b,revision=2 WHERE cafe_id=c AND user_id=owner_id;PERFORM set_config('erp.branch_expected',jsonb_build_object('branchId',branch_b,'revision',2)::text,true);
 PERFORM pg_temp.assert(jsonb_array_length(public.erp_purchase_credit_read(c))=0,'other branch cannot read credit');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'post',payload,post_request);EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'cached result cannot bypass changed branch');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'draft',jsonb_build_object('id',v_note,'revision',2),gen_random_uuid());EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'other branch cannot mutate existing credit');
 UPDATE public.erp_branch_scopes SET branch_id=branch_a,revision=3 WHERE cafe_id=c AND user_id=owner_id;PERFORM set_config('erp.branch_expected',jsonb_build_object('branchId',branch_a,'revision',3)::text,true);
