 result:=public.erp_purchase_credit_write(c,'draft',jsonb_build_object('id',v_note,'revision',2),gen_random_uuid());reversal:=(result->>'reversalId')::uuid;
 PERFORM pg_temp.assert((brand_finance_private.document_state(c,v_doc)->>'outstanding')::numeric=0,'draft conversion offsets first payable');
 PERFORM pg_temp.assert((SELECT sum(j.credit-j.debit)=115 FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id WHERE j.cafe_id=c AND j.party_id=supplier AND a.code='2000'),'draft conversion restores actual supplier debt');
 PERFORM pg_temp.assert((SELECT reversal_document_id=reversal FROM public.erp_purchase_credit_postings WHERE document_id=v_doc AND note_id=v_note LIMIT 1),'reversal history retained');
 result:=public.erp_purchase_credit_write(c,'post',jsonb_build_object('id',v_note,'revision',3,'expectedTotal',46),gen_random_uuid());second_document:=(result->>'documentId')::uuid;
 PERFORM pg_temp.assert(second_document<>v_doc AND(SELECT count(*)=2 FROM public.erp_purchase_credit_postings WHERE note_id=v_note),'reposting creates new immutable posting history');
 PERFORM pg_temp.assert(pg_temp.stock_hash(c)=stock_before AND pg_temp.source_hash(c,invoice)=source_before,'draft reversal and repost preserve stock/source hash');
