 PERFORM pg_temp.assert(public.erp_purchase_credit_write(c,'payment',payload,payment_request)=result,'payment retry posts once');
 PERFORM pg_temp.assert((brand_finance_private.document_state(c,second_document)->>'outstanding')::numeric=26,'actual partial settlement decreases extra payable');
 PERFORM pg_temp.assert((SELECT count(*)=1 FROM public.bf_documents WHERE cafe_id=c AND reference_id=second_document AND kind='settlement'),'exactly one actual settlement');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'draft',jsonb_build_object('id',v_note,'revision',5),gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLSTATE IN('P0001','22023','22003','23514');END;PERFORM pg_temp.assert(denied,'settled credit cannot revert to draft');
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'payment',payload||jsonb_build_object('revision',5,'amount',27),gen_random_uuid());EXCEPTION WHEN OTHERS THEN denied:=SQLSTATE IN('P0001','22023','22003','23514');END;PERFORM pg_temp.assert(denied,'overpayment rejected atomically');
 PERFORM pg_temp.assert((brand_finance_private.document_state(c,second_document)->>'outstanding')::numeric=26,'overpayment failure preserves debt');
