 denied:=false;BEGIN PERFORM public.erp_purchase_credit_write(c,'save',p||jsonb_build_object('id',gen_random_uuid()),gen_random_uuid());EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'read-only role cannot save credit');
