 delete_request:=gen_random_uuid();PERFORM public.erp_purchase_credit_write(c,'save',p||jsonb_build_object('id',delete_id),gen_random_uuid());payload:=jsonb_build_object('id',delete_id,'revision',1);result:=public.erp_purchase_credit_write(c,'delete',payload,delete_request);PERFORM pg_temp.assert(public.erp_purchase_credit_write(c,'delete',payload,delete_request)=result,'delete retry preserves safe result after physical draft deletion');
