 claims:=jsonb_build_object('sub',owner_id,'role','authenticated','amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',extract(epoch FROM now())::bigint)));PERFORM set_config('request.jwt.claims',claims::text,true);PERFORM public.cancel_brand_account(c,'purchase-credit-rollback-probe','isolated rollback test',gen_random_uuid());
 denied:=false;BEGIN PERFORM public.erp_purchase_credit_read(c);EXCEPTION WHEN SQLSTATE '42501' THEN denied:=true;END;PERFORM pg_temp.assert(denied,'archived brand credit reader denied');
